// TestIntegrationPipeline is the plugin-pipeline AC-1 golden: it drives the FULL
// Phase A pipeline (api -> scan -> enrich -> {module, plugin} -> store) with REAL
// go-plugin subprocesses (base-scanner + tv-parser) + REAL ffprobe + REAL HTTP,
// and asserts the provenance/view/stages/lifecycle contract end-to-end. It reuses
// the scan-library integration_test.go harness (binary build, temp DB, free port,
// real client, skip rules) and adds only the pipeline-specific assertions:
// sources["tv-parser"], _provenance, _view, _stages, status, and the ?status=
// filter. It is the single end-to-end proof of the plugin-pipeline (seam
// S-integration + the now-live metadatav1/commonv1 imports, S-proto); jointly it
// exercises S1..S11.
//
// Skips cleanly under -short / missing ffprobe|ffmpeg (INV-skip-clean, mirroring
// integration_test.go INV4). Expected season/episode/title are DERIVED from the
// fixture filename (INV-reviewer-independence), not magic constants — the reviewer
// re-derives them independently at the Acceptance Gate.
package mellifera_test

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

func TestIntegrationPipeline(t *testing.T) {
	if testing.Short() {
		t.Skip("pipeline integration test: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — skipping AC-1 pipeline golden (INV-skip-clean)")
	}
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not on PATH — cannot generate the real media fixture AC-1 requires")
	}

	// REAL subprocesses: build the server + base-scanner + tv-parser binaries (the
	// go-plugin substrate launches each as its own process; INV-real-subprocess).
	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "ip-mellifera-server", "./cmd/mellifera")
	scannerBin := buildBinary(t, tmp, "ip-base-scanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "ip-tv-parser", "./plugins/tv-parser")
	fixtureRoot := ipWriteFixtures(t)

	token := "ip-pipeline-admin-token"
	baseURL := startServer(t, serverBin, scannerBin, tvParserBin, tmp, token)
	client := &http.Client{Timeout: httpTimeout}

	libID := createLibrary(t, client, baseURL, token, fixtureRoot) // module "tv" -> 3 metadata_sources
	res := scanLibrary(t, client, baseURL, token, libID)

	// Independently derived counts: 2 ffmpeg-generated media + 1 zero-byte
	// corrupt.mkv are regular .mkv files under root => discovered/persisted 3.
	if res.Discovered != 3 {
		t.Fatalf("AC-1: discovered = %d, want 3 (2 media + corrupt.mkv)", res.Discovered)
	}
	if res.Persisted != 3 {
		t.Fatalf("AC-1: persisted = %d, want 3", res.Persisted)
	}
	// AC-6 (pipeline soft-fail): the unloaded external enrichers (kinopoisk, tmdb)
	// soft-fail per item and surface in scan warnings — yet the scan SUCCEEDED
	// (reached here) and every file was persisted.
	if !ipWarnsAboutAll(res.Warnings, "kinopoisk", "tmdb") {
		t.Errorf("AC-6: scan warnings missing an unloaded-enricher soft-fail; warnings=%v", res.Warnings)
	}

	byRel := indexByPath(t, listItems(t, client, baseURL, token, libID))

	t.Run("AC1_golden_provenance_state", func(t *testing.T) {
		ipAssertGolden(t, byRel)
		ipAssertCyrillic(t, byRel)
	})
	t.Run("AC1_parseTV_split", func(t *testing.T) {
		ipAssertParseTVSplit(t, byRel)
	})
	t.Run("AC6_soft_fail", func(t *testing.T) {
		ipAssertCorruptSoftFail(t, byRel)
		ipAssertSoftFailStages(t, byRel)
	})
	t.Run("AC7_status_filter", func(t *testing.T) {
		ipAssertStatusFilter(t, client, baseURL, token, libID)
	})

	// Idempotent re-scan: PutItem upserts by file_id, no duplicates, state stable.
	second := scanLibrary(t, client, baseURL, token, libID)
	if second.Persisted != res.Persisted {
		t.Fatalf("re-scan persisted = %d, want %d (idempotent upsert by file_id)", second.Persisted, res.Persisted)
	}
	if got := len(listItems(t, client, baseURL, token, libID)); got != len(byRel) {
		t.Fatalf("re-scan changed item count: %d -> %d (expected idempotent)", len(byRel), got)
	}
}

// ipWriteFixtures builds the pipeline fixture tree under a temp dir: one primary
// golden TV file, one Cyrillic TV file (proves non-ASCII titles survive the
// subprocess parse + are stamped into sources/_view), and one zero-byte file that
// drives the AC-6 unprobeable soft-fail. All three are real on-disk files.
func ipWriteFixtures(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	makeMedia(t, filepath.Join(root, "Show.Name.S01E02.1080p.mkv"))
	makeMedia(t, filepath.Join(root, "Игра престолов S01E01.mkv"))
	mustWrite(t, filepath.Join(root, "corrupt.mkv"), nil) // zero-byte -> AC-6 soft-fail
	return root
}

// ipAssertGolden asserts the full AC-1 + AC-5 + AC-7 contract for the primary
// fixture. Expected title/season/episode are DERIVED from the filename here
// (ipDeriveShow), not hardcoded — the golden-test rule.
func ipAssertGolden(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	const rel = "Show.Name.S01E02.1080p.mkv"
	it, ok := byRel[rel]
	if !ok {
		t.Fatalf("AC-1: golden %q not persisted; have %v", rel, ipPaths(byRel))
	}
	wantTitle, wantSeason, wantEpisode, ok := ipDeriveShow(strings.TrimSuffix(filepath.Base(rel), filepath.Ext(rel)))
	if !ok {
		t.Fatalf("AC-1: fixture %q did not yield a derivable SxxExx token (test bug)", rel)
	}
	doc := ipParseDoc(t, it.Document)

	// AC-1: sources["tv-parser"] carries the TV parse (title cleaned, resolution
	// stripped from the title, season/episode from the SxxExx token).
	tv, ok := doc.Sources["tv-parser"]
	if !ok {
		t.Fatalf("AC-1: sources[\"tv-parser\"] missing (sources=%v)", doc.Sources)
	}
	if got := ipStr(tv, "title"); got != wantTitle {
		t.Errorf("AC-1: sources.tv-parser.title = %q, want %q", got, wantTitle)
	}
	if got := ipInt(tv, "season"); got != wantSeason {
		t.Errorf("AC-1: sources.tv-parser.season = %d, want %d", got, wantSeason)
	}
	if got := ipInt(tv, "episode"); got != wantEpisode {
		t.Errorf("AC-1: sources.tv-parser.episode = %d, want %d", got, wantEpisode)
	}
	if got := ipStr(tv, "resolution"); got != "1080p" {
		t.Errorf("AC-1: sources.tv-parser.resolution = %q, want 1080p (stripped from title)", got)
	}

	// AC-5: each enriched field carries a _provenance entry naming tv-parser.
	ipAssertProvenance(t, doc, "tv-parser", []string{"title", "season", "episode"})

	// AC-1: _view recomputed by the core, title populated + sourced.
	if v := doc.View["title"]; ipStr(v, "value") != wantTitle || ipStr(v, "source") != "tv-parser" {
		t.Errorf("AC-1: _view.title = %v, want {value:%q,source:tv-parser}", doc.View["title"], wantTitle)
	}

	// AC-1: _stages carries the parse stage — tv-parser advanced the item to parsed.
	if !ipStageHas(doc.Stages, "tv-parser", "parsed", "ok") {
		t.Errorf("AC-1: no _stages entry {tv-parser, advanced_to:parsed, ok}; stages=%v", doc.Stages)
	}

	// AC-7: the metadata_source chain advanced the item to enriched.
	if it.Status != "enriched" {
		t.Errorf("AC-7: %q status = %q, want enriched", rel, it.Status)
	}
	if got := ipStr(doc.Parsed, "relative_path"); got != rel {
		t.Errorf("AC-1: parsed.relative_path = %q, want %q", got, rel)
	}
}

// ipAssertCyrillic proves a non-ASCII title survives the full subprocess pipeline
// and is stamped authoritatively into sources/_view (Cyrillic preserved).
func ipAssertCyrillic(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	const rel = "Игра престолов S01E01.mkv"
	it, ok := byRel[rel]
	if !ok {
		t.Fatalf("AC-1: Cyrillic %q not persisted; have %v", rel, ipPaths(byRel))
	}
	wantTitle, wantSeason, wantEpisode, _ := ipDeriveShow(strings.TrimSuffix(filepath.Base(rel), filepath.Ext(rel)))
	doc := ipParseDoc(t, it.Document)
	tv := doc.Sources["tv-parser"]
	if got := ipStr(tv, "title"); got != wantTitle {
		t.Errorf("AC-1 Cyrillic: title = %q, want %q (Cyrillic preserved end-to-end)", got, wantTitle)
	}
	if s, e := ipInt(tv, "season"), ipInt(tv, "episode"); s != wantSeason || e != wantEpisode {
		t.Errorf("AC-1 Cyrillic: season/episode = %d/%d, want %d/%d", s, e, wantSeason, wantEpisode)
	}
	if it.Status != "enriched" {
		t.Errorf("AC-7 Cyrillic: status = %q, want enriched", it.Status)
	}
}

// ipAssertParseTVSplit is the structural/negative AC-1 proof: base-scanner's
// parsed namespace is media-type-agnostic (NO season/episode) while the TV parse
// comes SOLELY from sources["tv-parser"] — proving the extraction (Task 06/07).
func ipAssertParseTVSplit(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	for _, rel := range []string{"Show.Name.S01E02.1080p.mkv", "Игра престолов S01E01.mkv"} {
		it, ok := byRel[rel]
		if !ok {
			t.Fatalf("AC-1 split: %q not persisted; have %v", rel, ipPaths(byRel))
		}
		doc := ipParseDoc(t, it.Document)
		for _, bad := range []string{"season", "episode"} {
			if _, leak := doc.Parsed[bad]; leak {
				t.Errorf("AC-1 split: %q parsed.%q present — TV parse must come from tv-parser only", rel, bad)
			}
		}
		if s, e := ipInt(doc.Sources["tv-parser"], "season"), ipInt(doc.Sources["tv-parser"], "episode"); s < 0 || e < 0 {
			t.Errorf("AC-1 split: %q sources.tv-parser missing season/episode (=%v)", rel, doc.Sources["tv-parser"])
		}
	}
}

// ipAssertCorruptSoftFail proves AC-6: the zero-byte file is STILL persisted
// (identified without ffprobe) with an EMPTY ffprobe field. One bad file never
// aborts the scan.
func ipAssertCorruptSoftFail(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	it, ok := byRel["corrupt.mkv"]
	if !ok {
		t.Fatalf("AC-6: corrupt.mkv not persisted (an unprobeable file must still yield an item); have %v", ipPaths(byRel))
	}
	if fp := ipParseDoc(t, it.Document).Ffprobe; len(fp) != 0 {
		t.Errorf("AC-6: corrupt.mkv ffprobe = %d bytes, want empty (unprobeable soft-fail)", len(fp))
	}
}

// ipAssertSoftFailStages proves the AC-6 pipeline soft-fail: the seeded-but-unloaded
// external enrichers (kinopoisk, tmdb) are recorded as unavailable in _stages, yet
// the item still reached enriched via tv-parser.
func ipAssertSoftFailStages(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	it, ok := byRel["Show.Name.S01E02.1080p.mkv"]
	if !ok {
		t.Fatalf("AC-6: golden item missing; have %v", ipPaths(byRel))
	}
	doc := ipParseDoc(t, it.Document)
	for _, plugin := range []string{"kinopoisk", "tmdb"} {
		if !ipStageHas(doc.Stages, plugin, "", "unavailable") {
			t.Errorf("AC-6: no _stages entry {%s, status:unavailable}; stages=%v", plugin, doc.Stages)
		}
	}
}

// ipAssertStatusFilter proves AC-7 over HTTP: ?status=enriched returns ONLY the
// enriched items (the two TV-parsed files; corrupt.mkv is "new"), and each carries
// queryable provenance (AC-5 through the filtered listing).
func ipAssertStatusFilter(t *testing.T, c *http.Client, baseURL, token string, libID int64) {
	t.Helper()
	enriched := ipItemsByStatus(t, c, baseURL, token, libID, "enriched")
	if len(enriched) != 2 {
		t.Fatalf("AC-7: ?status=enriched returned %d items, want 2 (the two TV-parsed files)", len(enriched))
	}
	for _, it := range enriched {
		if it.Status != "enriched" {
			t.Errorf("AC-7: ?status=enriched returned item %q with status %q", it.RelativePath, it.Status)
		}
		if _, ok := ipParseDoc(t, it.Document).Sources["tv-parser"]; !ok {
			t.Errorf("AC-5: enriched item %q missing sources.tv-parser in filtered listing", it.RelativePath)
		}
	}
}

// ipDeriveShow independently extracts (title, season, episode) from a TV-style
// filename stem, NOT via the plugin's parseTV — the reviewer-independence rule.
// It scans bytes for the ASCII "S<digits>E<digits>" token (Cyrillic bytes are
// >=0x80 so they never match), deriving season/episode directly, and normalizes
// the prefix's "."/"_" separators to spaces for the title. Uses only stdlib
// string ops so no import beyond the integration_test.go baseline is needed.
func ipDeriveShow(stem string) (title string, season, episode int, ok bool) {
	up := strings.ToUpper(stem)
	sIdx := -1
	for i := 0; i+1 < len(up); i++ {
		if up[i] == 'S' && up[i+1] >= '0' && up[i+1] <= '9' {
			sIdx = i
			break
		}
	}
	if sIdx < 0 {
		return "", 0, 0, false
	}
	j := sIdx + 1
	for j < len(up) && up[j] >= '0' && up[j] <= '9' {
		season = season*10 + int(up[j]-'0')
		j++
	}
	if j >= len(up) || up[j] != 'E' {
		return "", 0, 0, false
	}
	j++
	for j < len(up) && up[j] >= '0' && up[j] <= '9' {
		episode = episode*10 + int(up[j]-'0')
		j++
	}
	title = strings.NewReplacer(".", " ", "_", " ").Replace(stem[:sIdx])
	title = strings.Join(strings.Fields(strings.Trim(title, "- ")), " ")
	return title, season, episode, true
}

// ipDoc is the navigated slice of the enriched document the pipeline asserts over.
type ipDoc struct {
	Parsed     map[string]any            `json:"parsed"`
	Ffprobe    json.RawMessage           `json:"ffprobe"`
	Sources    map[string]map[string]any `json:"sources"`
	Provenance map[string]map[string]any `json:"_provenance"`
	View       map[string]map[string]any `json:"_view"`
	Stages     []map[string]any          `json:"_stages"`
}

func ipParseDoc(t *testing.T, raw json.RawMessage) ipDoc {
	t.Helper()
	var d ipDoc
	if err := json.Unmarshal(raw, &d); err != nil {
		t.Fatalf("unmarshal document: %v (doc=%s)", err, raw)
	}
	return d
}

func ipAssertProvenance(t *testing.T, doc ipDoc, plugin string, fields []string) {
	t.Helper()
	for _, f := range fields {
		p, ok := doc.Provenance[f]
		if !ok {
			t.Errorf("AC-5: _provenance.%s missing", f)
			continue
		}
		if got := ipStr(p, "plugin_id"); got != plugin {
			t.Errorf("AC-5: _provenance.%s.plugin_id = %q, want %q", f, got, plugin)
		}
		if got := ipStr(p, "plugin_version"); got == "" {
			t.Errorf("AC-5: _provenance.%s.plugin_version empty", f)
		}
	}
}

// ipStageHas reports whether stages has an entry matching plugin_id (and, when
// non-empty, advanced_to + status). advanced_to is the parse-stage carrier.
func ipStageHas(stages []map[string]any, plugin, advancedTo, status string) bool {
	for _, s := range stages {
		if ipStr(s, "plugin_id") != plugin {
			continue
		}
		if status != "" && ipStr(s, "status") != status {
			continue
		}
		if advancedTo != "" && ipStr(s, "advanced_to") != advancedTo {
			continue
		}
		return true
	}
	return false
}

func ipItemsByStatus(t *testing.T, c *http.Client, baseURL, token string, id int64, status string) []itemDTO {
	t.Helper()
	var resp itemsResponse
	url := fmt.Sprintf("%s/api/v1/items?library=%d&status=%s&limit=200", baseURL, id, status)
	if st := doRequest(t, c, http.MethodGet, url, token, nil, &resp); st != http.StatusOK {
		t.Fatalf("list items status=%s: HTTP %d, want 200", status, st)
	}
	return resp.Items
}

func ipWarnsAboutAll(warnings []string, subs ...string) bool {
	for _, s := range subs {
		found := false
		for _, w := range warnings {
			if strings.Contains(w, s) {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

func ipStr(m map[string]any, k string) string { s, _ := m[k].(string); return s }

// ipInt reads a JSON numeric field (structpb emits numbers as float64); -1 = absent.
func ipInt(m map[string]any, k string) int {
	f, ok := m[k].(float64)
	if !ok {
		return -1
	}
	return int(f)
}

func ipPaths(byRel map[string]itemDTO) []string {
	out := make([]string, 0, len(byRel))
	for k := range byRel {
		out = append(out, k)
	}
	return out
}
